package dustin.cex.domains.kyc;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import dustin.cex.domains.edd.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.server.ResponseStatusException;

/** 본인의 실제 확정 기록 발견·원문 분리·확인 의미·커서·감사/HTTP 경계를 검증한다. */
class CustomerFinalNoticeIntegrationTest extends CustomerFinalTestSupport {
    @Autowired CustomerFinalNoticeService notices;
    CustomerFinalNoticeService.Page list(){return notices.list(customer.getId(),sid,null);}
    @Test void pendingAndRejectedDraftsProduceNoNotice() throws Exception {var r=draft();assertTrue(list().items().isEmpty());finalDecide(r,false,finalProof(r,false));assertTrue(list().items().isEmpty());}
    @Test void actualApprovalPublishesOneStableNoticeWithoutPrivateText() throws Exception {var r=approvedFinal();var page=list();assertEquals(1,page.items().size());assertEquals(r.payload().id(),page.items().getFirst().finalId());assertEquals(receipt.id(),page.items().getFirst().reviewId());assertEquals(page,list());String raw=json.writeValueAsString(page);for(String secret:List.of(explanation().text(),"기존 담당자의 비공개 처리 기록","reasonMac","payloadHash","requester","checker"))assertFalse(raw.contains(secret));assertEquals(1,active());}
    @Test void listAndFinalGetDoNotPretendAcknowledged() throws Exception {approvedFinal();list();finals.ownFinal(customer.getId(),sid,receipt.id());assertNull(list().items().getFirst().acknowledgedAt());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_review_final_acknowledgments WHERE user_id=?",Long.class,customer.getId()));}
    @Test void explicitAckUpdatesMetadataWithoutRemovingNotice() throws Exception {var r=approvedFinal();var ack=finals.acknowledge(customer.getId(),sid,receipt.id(),r.payload().id(),UUID.randomUUID());assertEquals(1,list().items().size());assertEquals(ack.acknowledgedAt(),list().items().getFirst().acknowledgedAt());}
    @Test void otherCustomerAndOperatorCannotReceiveOwnersNotice() throws Exception {approvedFinal();var u=users.saveAndFlush(dustin.cex.domains.auth.model.entity.User.builder().email(UUID.randomUUID()+"@test.invalid").passwordHash(hash).build());var t=tokens.saveAndFlush(dustin.cex.domains.auth.model.entity.RefreshToken.builder().userId(u.getId()).tokenHash(UUID.randomUUID().toString()).expiresAt(LocalDateTime.now().plusHours(1)).build());assertTrue(notices.list(u.getId(),t.getSessionId(),null).items().isEmpty());assertThrows(ResponseStatusException.class,()->notices.list(maker.user().getId(),maker.sid(),null));}
    @Test void foreignRevokedAndDisabledSessionsCannotList() throws Exception {approvedFinal();assertThrows(ResponseStatusException.class,()->notices.list(customer.getId(),maker.sid(),null));var t=tokens.findBySessionId(sid).orElseThrow();t.setRevoked(true);tokens.saveAndFlush(t);assertThrows(ResponseStatusException.class,this::list);t.setRevoked(false);tokens.saveAndFlush(t);var u=users.findById(customer.getId()).orElseThrow();u.setEnabled(false);users.saveAndFlush(u);assertThrows(ResponseStatusException.class,this::list);}
    @Test void malformedCursorsAreRejected(){for(var c:List.of(new CustomerFinalNoticeService.Cursor(null,UUID.randomUUID()),new CustomerFinalNoticeService.Cursor(Instant.now(),null),new CustomerFinalNoticeService.Cursor(Instant.EPOCH.minusNanos(1),UUID.randomUUID()),new CustomerFinalNoticeService.Cursor(Instant.now().plusSeconds(60),UUID.randomUUID())))assertThrows(ResponseStatusException.class,()->notices.list(customer.getId(),sid,c));}
    @Test void realTwoResultsUseStrictStableCursorWithoutDuplicateFirst() throws Exception {approvedFinal();var first=list().items().getFirst();var second=requests.submit(customer.getId(),sid,UUID.randomUUID(),new CustomerExitReviewService.Submission("두 번째 요청"));requests.inspect(maker.user().getId(),maker.sid(),second.id());var n=notes.record(maker.user().getId(),maker.sid(),second.id(),UUID.randomUUID(),new CustomerReviewNoteService.Facts(CustomerReviewNoteService.Progress.INVESTIGATING,"두 번째 근거"));var r=finals.propose(maker.user().getId(),maker.sid(),second.id(),UUID.randomUUID(),n.id(),explanation());finalDecide(r,true,finalProof(r,true));var all=list();assertEquals(2,all.items().size());var newest=all.items().getFirst();assertEquals(r.payload().id(),newest.finalId());var after=notices.list(customer.getId(),sid,new CustomerFinalNoticeService.Cursor(newest.decidedAt(),newest.finalId()));assertEquals(1,after.items().size());assertEquals(first.finalId(),after.items().getFirst().finalId());assertNull(after.next());}
    @Test void laterTransferAndFinancialRescissionDoNotEraseNotice() throws Exception {approvedFinal();var before=list();approveWithdrawal(withdraw(UUID.randomUUID()));transfer();assertEquals(before,list());}
    @Test void auditFailureReturnsNoNoticeAndCreatesNoAcknowledgment() throws Exception {approvedFinal();doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_FINAL_NOTICES_LISTED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,this::list);reset(audit);assertNull(list().items().getFirst().acknowledgedAt());}
    @Test void httpCustomerOnlyNoStoreAndCursorValidation() throws Exception {var r=approvedFinal();String path="/api/customer/relationship/final-notices";String body=mvc.perform(get(path).header("Authorization","Bearer "+customerAccess)).andExpect(status().isOk()).andExpect(header().string("Cache-Control",org.hamcrest.Matchers.containsString("no-store"))).andReturn().getResponse().getContentAsString();assertTrue(body.contains(r.payload().id().toString()));mvc.perform(get(path).header("Authorization","Bearer "+maker.access())).andExpect(status().isForbidden());mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).header("Authorization","Bearer "+customerAccess).param("afterFinal",UUID.randomUUID().toString())).andExpect(status().isBadRequest());}
}
